"""Machan pop-up hook (Swatch, Oct 20 2026 ICT). `import mw_machan_pop` at the top of a deck build script:
on exit, every .html under the repo written during the run that has a 'Built by Machan' footer gets the
'Meet Machan' pop-up (footer no longer links out), the html,body overflow-x clip (Back taps can't widen 390px) and,
for new pages, the small cover date line ('Oct 20'). Plain HTML only; locking stays with lock_pages.py."""
import re,os,datetime
BLK='<!--mw-machan-pop v1--><style id="mwmp-css">html,body{overflow-x:hidden;max-width:100%}\n.mwmp-bg{position:fixed;inset:0;z-index:2147483000;display:none;align-items:center;justify-content:center;padding:20px;background:rgba(40,30,20,.28);-webkit-tap-highlight-color:transparent}\n.mwmp-bg.on{display:flex}\n.mwmp{position:relative;box-sizing:border-box;width:100%;max-width:300px;background:#FBF6EC;color:#3a2e25;border-radius:18px;padding:22px 22px 20px;text-align:center;box-shadow:0 6px 22px rgba(60,40,20,.14),0 1px 3px rgba(60,40,20,.08);font:15px/1.45 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;outline:none}\n.mwmp .mwmp-ic{margin:2px auto 10px;filter:drop-shadow(0 2px 3px rgba(120,60,30,.18))}\n.mwmp h2{margin:0 0 8px;font-size:18px;line-height:1.25;font-weight:700;color:#3a2e25}\n.mwmp p{margin:0 0 4px;font-size:14.5px;color:#5a4a3e}\n.mwmp p.mwmp-w{margin-top:10px;font-style:italic;color:#9a4a2c}\n.mwmp-x{position:absolute;top:8px;right:8px;width:32px;height:32px;border:0;border-radius:50%;background:transparent;color:#7a6a5e;font-size:20px;line-height:32px;padding:0;cursor:pointer}\n.mwmp-x:hover,.mwmp-x:focus-visible{background:rgba(120,90,60,.1);outline:2px solid #C8643F;outline-offset:1px}\n[data-mwmp]{cursor:pointer}\n.mw-made{margin:6px 0 0;font-size:12px;letter-spacing:.02em;opacity:.62;font-weight:500}</style><script id="mwmp-js">(function(){if(window.__mwmp)return;window.__mwmp=1;var bg,card,last,q=0;\nfunction build(){bg=document.createElement(\'div\');bg.className=\'mwmp-bg\';bg.innerHTML=\'<div class="mwmp" role="dialog" aria-modal="true" aria-labelledby="mwmp-t" tabindex="-1"><button type="button" class="mwmp-x" aria-label="Close">\\u00d7</button><svg class="mwmp-ic" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="44" height="44" aria-hidden="true" focusable="false" style="display:block;width:44px;height:44px"><path d="M12 5.2C11.2 3 9.4 2 7.6 2.3c.3 1.9 1.9 3.2 4.4 2.9z" fill="#3F7D58"/><path d="M12 5.2c.8-2.2 2.6-3.2 4.4-2.9-.3 1.9-1.9 3.2-4.4 2.9z" fill="#5E9A6E"/><rect x="3.5" y="5.5" width="17" height="16" rx="7" fill="#C8643F"/><rect x="5.5" y="9" width="13" height="10" rx="5" fill="#FAF6EE"/><circle cx="9.6" cy="13.3" r="1.35" fill="#2E6F86"/><path d="M13 13.1q1.4 1.25 2.8 0" fill="none" stroke="#2E6F86" stroke-width="1.1" stroke-linecap="round"/><path d="M10.6 16.1q1.4 1.1 2.8 0" fill="none" stroke="#C8643F" stroke-width="1.1" stroke-linecap="round"/><circle cx="7.6" cy="15.6" r=".9" fill="#E9B9A3"/><circle cx="16.4" cy="15.6" r=".9" fill="#E9B9A3"/></svg><h2 id="mwmp-t">Meet Machan</h2><p>A small persimmon with a long, lucky past.</p><p>He signs off on everything built here.</p><p class="mwmp-w">May everything go as you wish.</p></div>\';document.body.appendChild(bg);card=bg.firstChild;\n[\'click\',\'pointerdown\',\'pointerup\',\'mousedown\',\'mouseup\',\'touchstart\',\'touchend\'].forEach(function(t){bg.addEventListener(t,function(e){e.stopPropagation();if(t===\'click\'&&(e.target===bg||e.target.closest(\'.mwmp-x\'))){e.preventDefault();close()}},{passive:t.indexOf(\'touch\')<0})})}\nfunction open(e){if(e){e.preventDefault();e.stopPropagation();e.stopImmediatePropagation()}if(!bg)build();last=document.activeElement;bg.classList.add(\'on\');card.querySelector(\'.mwmp-x\').focus()}\nfunction close(){if(!bg||!bg.classList.contains(\'on\'))return;bg.classList.remove(\'on\');if(last&&last.focus)try{last.focus({preventScroll:true})}catch(_){}}\nwindow.addEventListener(\'keydown\',function(e){if(!bg||!bg.classList.contains(\'on\'))return;e.stopPropagation();e.stopImmediatePropagation();if(e.key===\'Escape\'||e.key===\'Esc\'){e.preventDefault();close()}else if(e.key===\'Tab\'){e.preventDefault();card.querySelector(\'.mwmp-x\').focus()}},true);\nfunction bind(){var els=document.querySelectorAll(\'a,button,.builtby\');for(var i=0;i<els.length;i++){var a=els[i];if(a.hasAttribute(\'data-mwmp\'))continue;var t=(a.textContent||\'\').replace(/\\s+/g,\' \').trim();if(!/^Built by Machan$/i.test(t))continue;a.setAttribute(\'data-mwmp\',\'\');if(a.tagName===\'A\'){a.removeAttribute(\'href\');a.removeAttribute(\'target\');a.removeAttribute(\'rel\');a.setAttribute(\'tabindex\',\'0\')}a.setAttribute(\'role\',\'button\');a.setAttribute(\'aria-haspopup\',\'dialog\');a.addEventListener(\'click\',open,true);a.addEventListener(\'keydown\',function(e){if(e.key===\'Enter\'||e.key===\' \'){open(e)}},true)}}\nif(document.readyState===\'loading\')document.addEventListener(\'DOMContentLoaded\',bind);else bind();setTimeout(bind,600);setTimeout(bind,2500);try{new MutationObserver(function(){if(q)return;q=1;setTimeout(function(){q=0;bind()},250)}).observe(document.documentElement,{childList:true,subtree:true})}catch(_){}})();</script><!--/mw-machan-pop-->'
def today():
    d=datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=7)))  # ICT
    return d.strftime('%b ')+str(d.day)
def apply(t,made=None):
    """Idempotent: add/replace the Machan pop-up block before </body>; made='Oct 20' adds the small cover date line after the first </h1>."""
    t=re.sub(r'<!--mw-machan-pop v\d+-->.*?<!--/mw-machan-pop-->','',t,flags=re.S)
    t=t.replace('href="https://maxweberman.com" target="_blank" rel="noopener">Built by Machan<','role="button" tabindex="0" aria-haspopup="dialog">Built by Machan<')
    if made and 'class="mw-made"' not in t:
        i=t.find('</h1>')
        if i>0: t=t[:i+5]+'<p class="mw-made">'+made+'</p>'+t[i+5:]
    t=media_stop(t)
    i=t.rfind('</body>')
    return t[:i]+BLK+t[i:] if i>=0 else t+BLK

# Media stop (Oct 20 2026 ICT): pause+reset every <audio>/<video>/Audio() on card change, swipe, Next/Back/Skip,
# answer-advance, Machan Decides, end/send screen and when the page is hidden; resets play buttons. Idempotent.
MS='<!--mw-media-stop v1--><script id="mw-media-stop">(function(){if(window.__mwms)return;window.__mwms=1;\nvar M=new Set(),P=HTMLMediaElement.prototype,op=P.play;P.play=function(){M.add(this);return op.apply(this,arguments)};\nvar PB=\'.playpill,.v-sound,.v-sound *,[data-audio],[data-mwplay],.mw-play,.playbtn,.play-btn,.pi,.pl\';\nfunction isPlay(el){try{return !!(el&&el.closest&&el.closest(PB))}catch(_){return false}}\nfunction stop(){var any=0;document.querySelectorAll(\'audio,video\').forEach(function(a){M.add(a)});\nM.forEach(function(a){try{if(!a.paused)any=1;a.pause();if(a.currentTime)a.currentTime=0}catch(_){}});\ntry{if(typeof window.stopAllAudio===\'function\')window.stopAllAudio()}catch(_){}\ntry{if(typeof window.setPillState===\'function\')window.setPillState()}catch(_){}\ndocument.querySelectorAll(\'.playpill,.v-sound,[data-audio],[data-mwplay]\').forEach(function(b){b.classList.remove(\'playing\');if(b.hasAttribute(\'aria-pressed\'))b.setAttribute(\'aria-pressed\',\'false\');var i=b.querySelector(\'.pi\');if(i&&/❚|■/.test(i.textContent))i.textContent=\'▶\'});return any}\nwindow.mwStopMedia=stop;\n/* wrap card-change functions (global function declarations) */\n[\'render\',\'go\',\'next\',\'back\',\'skip\',\'advance\',\'show\',\'showEnd\',\'toSend\',\'machanDecides\',\'decide\',\'finish\'].forEach(function(n){var f=window[n];if(typeof f!==\'function\'||f.__mwms)return;var w=function(){stop();return f.apply(this,arguments)};w.__mwms=1;try{window[n]=w}catch(_){}});\n/* taps on nav/answer controls (not the play button) */\ndocument.addEventListener(\'click\',function(e){var t=e.target;if(isPlay(t))return;if(t.closest&&t.closest(\'button,a,[role=button],.opt,.tile,.choice,[data-side],[data-act]\'))stop()},true);\n/* swipes */\nvar sx=null,sy=0;document.addEventListener(\'pointerdown\',function(e){sx=isPlay(e.target)?null:e.clientX;sy=e.clientY},true);\ndocument.addEventListener(\'pointerup\',function(e){if(sx!==null&&Math.abs(e.clientX-sx)>40&&Math.abs(e.clientX-sx)>Math.abs(e.clientY-sy))stop();sx=null},true);\ndocument.addEventListener(\'touchstart\',function(e){var p=e.touches[0];sx=isPlay(e.target)?null:p.clientX;sy=p.clientY},{capture:true,passive:true});\ndocument.addEventListener(\'touchend\',function(e){var p=e.changedTouches[0];if(sx!==null&&p&&Math.abs(p.clientX-sx)>40&&Math.abs(p.clientX-sx)>Math.abs(p.clientY-sy))stop();sx=null},{capture:true,passive:true});\ndocument.addEventListener(\'keydown\',function(e){if(/^Arrow(Left|Right)$|^Escape$/.test(e.key))stop()},true);\ndocument.addEventListener(\'visibilitychange\',function(){if(document.hidden)stop()});\nwindow.addEventListener(\'pagehide\',stop);window.addEventListener(\'hashchange\',stop);window.addEventListener(\'popstate\',stop);\n})();</script><!--/mw-media-stop-->\n'
def media_stop(t):
    t=re.sub(r'<!--mw-media-stop v\d+-->.*?<!--/mw-media-stop-->','',t,flags=re.S)
    if not re.search(r'<audio|<video|new Audio\(|\.mp3|\.mp4',t): return t
    i=t.rfind('</body>')
    return t[:i]+MS+t[i:] if i>=0 else t+MS

import atexit,time
from pathlib import Path
_T0=time.time()-1
_FOOT=re.compile(r'>\s*(?:<[^>]+>\s*)*Built by Machan\s*<')
def _hook():
    root=Path(__file__).resolve().parent.parent
    for f in root.rglob('*.html'):
        if '.git' in f.parts or 'tools' in f.parts: continue
        try:
            if f.stat().st_mtime<_T0: continue
            t=f.read_text()
        except Exception: continue
        if "K='mwPagesKey'" in t: continue
        n=apply(t,made=today()) if _FOOT.search(t) else media_stop(t)
        if n!=t: f.write_text(n)
atexit.register(_hook)
